// HasKey applies the HasEdge predicate on the "key" edge.
func HasKey() predicate.UpstreamKeyModelRoute {
	return predicate.UpstreamKeyModelRoute(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, KeyTable, KeyColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasKeyWith applies the HasEdge predicate on the "key" edge with a given conditions (other predicates).
func HasKeyWith(preds ...predicate.UpstreamKey) predicate.UpstreamKeyModelRoute {
	return predicate.UpstreamKeyModelRoute(func(s *sql.Selector) {
		step := newKeyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.UpstreamKeyModelRoute) predicate.UpstreamKeyModelRoute {
	return predicate.UpstreamKeyModelRoute(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.UpstreamKeyModelRoute) predicate.UpstreamKeyModelRoute {
	return predicate.UpstreamKeyModelRoute(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.UpstreamKeyModelRoute) predicate.UpstreamKeyModelRoute {
	return predicate.UpstreamKeyModelRoute(sql.NotPredicates(p))
}
